import { Treemodel } from './treemodel';
import * as $ from 'jquery';

@Component({
  selector: 'app-multi-treelist',
  templateUrl: './multi-treelist.component.html',
  styleUrls: ['./multi-treelist.component.css']
})
export class MultiTrellistComponent implements OnInit {
  treemodel: Treemodel;

  constructor() {}

  ngOnInit(): void {
    this.treemodel = new Treemodel();
  }

  expandNode(nodeId: string): void {
    if (!this.treemodel.nodes[nodeId]) return;

    let currentLevel = 0;

    const toggleNode = (node: any) => {
      node.expanded = !node.expanded;
    };

    // Traverse the tree starting from the given nodeId
    function traverse(currentNode: TreeNode | undefined, level: number): void {
      if (!currentNode || currentNode.id !== nodeId) return;

      if (currentLevel === level) {
        toggleNode(currentNode);
      }
      currentLevel++;

      if (currentNode.children && currentNode.children.length > 0) {
        traverse(currentNode.children[0], level + 1); // Start at first child
      }
    }

    traverse(this.treemodel.nodes.find(n => n.id === nodeId), 0);
  }

  collapseNode(nodeId: string): void {
    if (!this.treemodel.nodes[nodeId]) return;

    const toggleNode = (node: any) => {
      node.expanded = false;
    };

    traverse(this.treemodel.nodes.find(n => n.id === nodeId), 0);

    $(`#${nodeId}`).children().prop('aria-expanded', false);
  }
}
```

